 downloads=''.join(f'<a class="download" href="{url}" download><div><span class="tag">{tag}</span><h3>{h}</h3><p>{p}</p></div><span class="arrow" aria-hidden="true">↓</span></a>' for tag,h,p,url in resources)
 actions=[(t('Réunir le premier cercle','Assemble the first group'),t('Identifier 2 ou 3 ordinateurs, leurs systèmes et leurs connexions. Choisir un modèle, des tâches et des critères de succès comparables.','Identify 2 or 3 computers, their operating systems and connections. Choose a model, tasks and comparable success criteria.'),t('Prochaine étape technique','Next technical step')),(t('Construire le pilote et choisir la licence','Build the pilot and choose a licence'),t('Intégrer un moteur, la découverte, l’authentification, les quotas et la reprise. Faire relire le code et décider de la licence de redistribution.','Integrate an engine, discovery, authentication, quotas and recovery. Have the code reviewed and decide on a redistribution licence.'),t('Développement requis','Development required')),(t('Mesurer sur de vraies machines','Measure on real computers'),t('Comparer une machine seule au cercle, puis tester les pannes, la qualité des réponses et la consommation électrique.','Compare a single computer with the group, then test failures, response quality and electricity use.'),t('Mesures à réaliser','Measurements pending')),(t('Tester avant le rendez-vous mondial','Test before the worldwide event'),t('D’abord un réseau local, puis 2 ou 3 adresses Internet, une bêta et une répétition. Fixer ensuite seulement une date et une heure UTC.','Start on a local network, then 2 or 3 internet locations, a beta and a rehearsal. Only then set a UTC date and time.'),t('Aucune date annoncée','No date announced'))]
 roadmap=''.join(f'<li><span class="num">0{i+1}</span><div><strong>{h}</strong><p>{p}</p></div><span class="state">{state}</span></li>' for i,(h,p,state) in enumerate(actions))
 groups=[]
